"""Regenerate rules/INDEX.md: one line per rule, grouped by module. Run after editing a rule.

usage: python3 tools/build_index.py
A rule is a bullet `- **ID. Title.**` or a table row `| ID | Form | ... |` whose first
cell is a rule ID (a capital letter and a number).
"""
import re
from pathlib import Path

RULES = Path(__file__).resolve().parent.parent / 'rules'
SKIP = {'README.md', 'INDEX.md', 'conflicts.md'}

out = ['# Rule index', '',
       'Generated by `tools/build_index.py`. Read the module, not this file, before applying a rule.', '']
total = 0
for f in sorted(RULES.glob('*.md')):
    if f.name in SKIP:
        continue
    text = f.read_text(encoding='utf-8')
    title = text.splitlines()[0].lstrip('# ').strip()
    rows = []
    for line in text.splitlines():
        m = re.match(r'- \*\*([A-Z]\d+)\. (.+?)\*\*', line) or re.match(r'## ([A-Z]\d+)\. (.+)', line)
        t = re.match(r'\| ([A-Z]\d+) \| (.+?) \|', line)
        if m:
            rows.append('- %s %s' % (m.group(1), m.group(2).rstrip('.')))
        elif t:
            rows.append('- %s %s' % (t.group(1), t.group(2)))
    if rows:
        out += ['## %s (`%s`)' % (title, f.name), ''] + rows + ['']
        total += len(rows)
out.insert(3, '%d rules.' % total)
(RULES / 'INDEX.md').write_text('\n'.join(out), encoding='utf-8')
print(total, 'rules indexed')
